/* Character sheet V2: presentation and explicit equipment actions. */
window.ND_SHEET_V2=(()=>{
 const V=()=>window.ND_CATALOG_V2;
 const sign=n=>n<0?'−'+Math.abs(n):'+'+n;
 const stateNames={inventory:'В инвентаре',equipped:'Экипирован',installed:'Установлен',loaded:'Загружен в деку',learned:'Изучен',consumed:'Израсходован'};
 const categoryFor=item=>V().classes.find(c=>c.id===item.classId)?.category||item.legacy?.category||item.category;
 let computed=null,normalized=null,items=[],byId=new Map();
 let checkState={attributeId:'reflexes',skillId:'shooting',weaponId:'',distance:''};
 function prepare(){items=V().all(D.catalog);byId=new Map(items.map(x=>[x.catalogId,x]));normalized=V().normalizeCharacter(card,D.catalog);computed=V().calculateCharacterStats(card,D.catalog);}
 const itemFor=x=>byId.get(x.catalogId)||x.snapshot||{name:'Неизвестный предмет',classId:null,description:''};
 const itemName=x=>x.displayName||x.name||'Неизвестный предмет';
 const className=id=>V().classes.find(x=>x.id===id)?.label||'Требует классификации';
 function bonus(type,index){const id=(type==='attributes'?V().attributeIds:V().skillIds)[index],stat=computed?.[type]?.[id];if(!stat?.permanentBonus)return '';const sourceLabel=stat.sources.every(s=>s.location==='installed')?'ХРОМ':'ЭКИПИРОВКА';return `<details class="v2-stat-bonus"><summary><span class="v2-bonus-chip">${sign(stat.permanentBonus)} <small>${sourceLabel}</small></span><span class="v2-effective">Итого ${sign(stat.effective)}</span></summary><div class="v2-source-list"><span>База ${sign(stat.base)}</span>${stat.sources.map(s=>`<span>${esc(s.name||itemName(byId.get(s.itemId)||{}))} <b>${sign(s.value)}</b></span>`).join('')}<strong>Итог проверки ${sign(stat.effective)}</strong></div></details>`;}
 function parameters(item){const stats=item.stats||{},eq=item.equipment||{},out=[];const add=(label,value)=>{if(value!==undefined&&value!==null&&value!=='')out.push('<span>'+esc(label)+': '+esc(value)+'</span>');};add('Урон',stats.damage??item.damage);if(stats.rangeMin!=null||stats.rangeMax!=null)add('Дальность',(stats.rangeMin??'?')+'–'+(stats.rangeMax??'?')+' гекс.');else add('Дальность',item.range);add('Досягаемость',stats.reach);add('Хват',stats.hands??item.slot);if(['implant','neurodeck'].includes(item.classId))add('Хром',eq.chromeSlots??item.slots);if(item.classId==='clothing_armor')add('Броня',stats.armor??item.armor);if(item.classId==='neurodeck'){add('Черви',eq.wormCapacity);add('Демоны',eq.demonCapacity);}if(['worm','heavy_demon'].includes(item.classId)){add('Цель',stats.target??item.target);add('СЛ',stats.difficulty??item.difficulty);}add('Длительность',stats.duration);return out.length?'<div class="item-tags v2-item-parameters">'+out.join('')+'</div>':'';}
 function perkHint(x,item){if(item.classId!=='perk')return '';if(x.metadata?.learned===true||x.location==='learned'||x.legacySlot?.category==='perks')return '<p class="hint v2-perk-cost">Перк уже изучен. Повторное включение не списывает ОО; снятие не возвращает опыт.</p>';const price=item.economy?.price;return '<p class="hint v2-perk-cost">'+(Number.isSafeInteger(price)?'Первое изучение: <b>'+price+' ОО</b>. Спишется один раз при выборе «Изучен». Доступно: '+(card.experience??0)+' ОО.':'Стоимость изучения не задана. Мастер должен указать её в справочнике.')+'</p>';}
 function stateOptions(x,item){const target=V().stateFor(item);return [...new Set(['inventory',...(target?[target]:[]),x.location])].map(value=>`<option value="${value}" ${x.location===value?'selected':''}>${stateNames[value]}</option>`).join('');}
 function row(x,{full=false}={}){const item=itemFor(x),isConsumable=V().isConsumable(item);return `<article class="v2-owned-item ${x.location==='consumed'?'is-consumed':''}"><div class="v2-owned-heading"><span class="eyebrow">${esc(className(item.classId))}</span><span class="v2-state-label">${esc(stateNames[x.location]||x.location)}</span></div>${typeof catalogIcon==='function'?catalogIcon(item,'v2-item-icon'):''}<h3>${esc(itemName(item))}</h3>${parameters(item)}${perkHint(x,item)}${item.archived?'<span class="v2-archive-tag">Архив · сохранённый экземпляр</span>':''}<details class="v2-item-rules"><summary>Описание и правила</summary><p>${esc(item.description||'Описание не задано')}</p>${item.rulesText&&item.rulesText!==item.description?`<p>${esc(item.rulesText)}</p>`:''}${item.effects?.filter(e=>e.type==='temporary_effect'||e.type==='conditional_modifier'||e.type==='rules_only').length?'<p class="hint">Условные и временные эффекты не прибавляются к постоянному бонусу листа.</p>':''}</details><div class="v2-owned-controls"><label class="field"><span>Состояние</span><select data-v2-state="${esc(x.instanceId)}" aria-label="Состояние: ${esc(itemName(item))}" ${!canEdit||x.quantity===0?'disabled':''}>${stateOptions(x,item)}</select></label><label class="field v2-quantity"><span>Количество</span><input data-v2-quantity="${esc(x.instanceId)}" aria-label="Количество: ${esc(itemName(item))}" type="number" min="0" max="999" step="1" value="${x.quantity}" ${!canEdit?'disabled':''}></label></div>${['implant','neurodeck'].includes(item.classId)?`<label class="field"><span>Качество</span><input data-v2-quality="${esc(x.instanceId)}" value="${esc(x.metadata?.quality||'')}" maxlength="200" ${!canEdit?'disabled':''}></label>`:''}<div class="v2-item-actions">${isConsumable?`<button data-v2-consume="${esc(x.instanceId)}" ${!canEdit||x.quantity<1?'disabled':''}>Использовать 1 шт.</button>`:''}${full?`<button data-v2-remove="${esc(x.instanceId)}" class="outline" ${!canEdit?'disabled':''}>Убрать из владения</button>`:''}</div></article>`;}
 function equipment(category){const rows=normalized.equipmentItems.filter(x=>categoryFor(itemFor(x))===category&&!(category==='implants'&&itemFor(x).classId==='neurodeck')&&(category==='consumables'?x.location!=='consumed':!['inventory','consumed'].includes(x.location)&&x.equipped!==false)&&x.quantity>0);return `${category==='programs'?`<div class="v2-program-capacity"><span>Черви <b>${computed.programs.worms} / ${computed.programCapacity.worms}</b></span><span>Демоны <b>${computed.programs.demons} / ${computed.programCapacity.demons}</b></span></div><p class="hint">Загрузка программы в деку не означает её запуск.</p>`:''}${rows.map(x=>row(x)).join('')||'<p class="empty">Нет активных предметов.</p>'}<div class="v2-equipment-footer"><button type="button" data-v2-inventory>Открыть инвентарь ↗</button>${canEdit?`<button type="button" data-v2-add="${category}">+ Из справочника</button>`:''}</div>`;}
 function decks(){const rows=normalized.equipmentItems.filter(x=>itemFor(x).classId==='neurodeck'&&x.location==='installed'&&x.quantity>0);return section('Нейродеки',rows.map(x=>row(x)).join('')||'<p class="empty">Нейродека не установлена</p>');}
 function inventory(){return window.ND_INVENTORY.render();}
 function checks(){return `<section class="panel v2-check-panel"><header class="panel-head"><h2>Проверка 2d12</h2><span>БАЗА + СНАРЯЖЕНИЕ</span></header><div class="v2-check-fields"><label class="field"><span>Характеристика</span><select id="v2-check-attribute">${V().attributeIds.map((id,i)=>`<option value="${id}" ${checkState.attributeId===id?'selected':''}>${esc(D.attributes[i].name)}</option>`).join('')}</select></label><label class="field"><span>Навык</span><select id="v2-check-skill">${V().skillIds.map((id,i)=>`<option value="${id}" ${checkState.skillId===id?'selected':''}>${esc(D.skills[i].name)}</option>`).join('')}</select></label></div><details class="v2-check-context"><summary>Контекст проверки</summary><div class="v2-check-fields"><label class="field"><span>Активное оружие</span><select id="v2-check-weapon"><option value="">Без контекста оружия</option>${normalized.equipmentItems.filter(x=>x.location==='equipped'&&['ranged_weapon','melee_weapon'].includes(itemFor(x).classId)).map(x=>`<option value="${esc(x.catalogId)}" ${checkState.weaponId===x.catalogId?'selected':''}>${esc(itemName(itemFor(x)))}</option>`).join('')}</select></label><label class="field"><span>Дистанция, гексы</span><input id="v2-check-distance" type="number" min="0" step="1" placeholder="Не задана" value="${esc(checkState.distance)}"></label></div></details><div id="v2-check-breakdown" class="v2-check-breakdown" aria-live="polite"></div><div class="v2-roll-line"><button id="v2-roll" class="yellow">Бросить 2d12</button><output id="v2-roll-result" aria-live="polite">Результат появится здесь</output></div></section>`;}
 function commit(next){if(!canEdit)throw Error('Карточка доступна только для просмотра');next=V().syncLegacyFromEquipment(next,D.catalog);const d=V().calculateCharacterStats(next,D.catalog);next.hp=Math.min(next.hp,d.maxHP);next.armorSpent=Math.min(next.armorSpent,d.armor);card=E.validate(next,D);changed();render();window.ND_INVENTORY?.refreshDetail();}
 function changeQuantity(id,value){if(!canEdit)throw Error('Карточка доступна только для просмотра');if(!Number.isSafeInteger(value)||value<0||value>999)throw Error('Количество: целое число от 0 до 999');let next=V().normalizeCharacter(card,D.catalog),x=next.equipmentItems.find(x=>x.instanceId===id);if(!x)throw Error('Предмет не найден');if(!value){next=V().setEquipmentState(next,D.catalog,id,'inventory');x=next.equipmentItems.find(x=>x.instanceId===id);}const previous=x.quantity;x.quantity=value;if(!value){x.location='consumed';x.equipped=false;}else if(x.location==='consumed'){x.location='inventory';x.equipped=false;}if(value>previous&&!['inventory','consumed'].includes(x.location))V().validateEquipmentState(next,D.catalog);commit(next);}
 function addDialog(category='all'){window.ND_INVENTORY.catalogDialog(category);}
 function equipArmor(catalogId){if(!canEdit)throw Error('Карточка доступна только для просмотра');let next=V().normalizeCharacter(card,D.catalog);const item=catalogId?V().resolve(D.catalog,catalogId):null;if(catalogId&&item?.classId!=='clothing_armor')throw Error('Выбери одежду или защиту из справочника');let target=item?next.equipmentItems.find(x=>x.catalogId===catalogId&&x.quantity>0&&x.location!=='consumed'):null;if(item?.archived&&!target)throw Error('Архивный предмет недоступен для получения');for(const x of next.equipmentItems){const entry=V().resolve(D.catalog,x.catalogId)||x.snapshot;if(entry?.classId==='clothing_armor'&&x.location==='equipped'&&x.equipped!==false&&x.instanceId!==target?.instanceId)next=V().setEquipmentState(next,D.catalog,x.instanceId,'inventory');}if(item){if(!target){next=V().addEquipment(next,D.catalog,catalogId);target=next.equipmentItems.at(-1);}if(target.location!=='equipped'||target.equipped===false)next=V().setEquipmentState(next,D.catalog,target.instanceId,'equipped');}commit(next);}
 function check(){const input=$('#v2-check-distance'),distance=input?.value===''?undefined:Number(input.value);if(distance!==undefined&&(!Number.isFinite(distance)||distance<0))throw Error('Дистанция должна быть неотрицательной');checkState={attributeId:$('#v2-check-attribute').value,skillId:$('#v2-check-skill').value,weaponId:$('#v2-check-weapon').value,distance:input?.value||''};return V().calculateCheckModifier(card,D.catalog,{attributeId:checkState.attributeId,skillId:checkState.skillId,context:{weaponId:checkState.weaponId||undefined,distanceHexes:distance}});}
 function updateCheck(){try{const c=check();$('#v2-check-breakdown').innerHTML=`<strong>Модификатор ${sign(c.modifier)}</strong><span>Характеристика ${sign(c.attribute.effective)} + навык ${sign(c.skill.effective)}${c.conditionalBonus?' · условия '+sign(c.conditionalBonus):''}</span><small>Базовые значения: ${sign(c.attribute.base)} и ${sign(c.skill.base)}. Бонусы снаряжения: ${sign(c.attribute.permanentBonus+c.skill.permanentBonus)}.</small>${c.sources.length?`<small>${c.sources.map(s=>esc(s.name)+' '+sign(s.value)).join(' · ')}</small>`:''}`;$('#v2-roll').disabled=false;}catch(e){$('#v2-check-breakdown').textContent=e.message;$('#v2-roll').disabled=true;}}
 function bind(){document.querySelectorAll('[data-v2-add]').forEach(b=>b.onclick=()=>addDialog(b.dataset.v2Add));document.querySelectorAll('[data-v2-inventory]').forEach(b=>b.onclick=()=>{switchSheetTab('inventory');});document.querySelectorAll('[data-v2-state]').forEach(el=>el.onchange=()=>{if(!canEdit)return;try{commit(V().setEquipmentState(card,D.catalog,el.dataset.v2State,el.value));}catch(e){notify(e.message);render();}});document.querySelectorAll('[data-v2-quantity]').forEach(el=>el.onchange=()=>{if(!canEdit)return;try{changeQuantity(el.dataset.v2Quantity,Number(el.value));}catch(e){notify(e.message);render();}});document.querySelectorAll('[data-v2-quality]').forEach(el=>el.onchange=()=>{if(!canEdit)return;try{const next=V().normalizeCharacter(card,D.catalog),x=next.equipmentItems.find(x=>x.instanceId===el.dataset.v2Quality);x.metadata={...x.metadata,quality:el.value};commit(next);}catch(e){notify(e.message);}});document.querySelectorAll('[data-v2-consume]').forEach(b=>b.onclick=()=>{if(!canEdit)return;try{commit(V().consumeEquipment(card,D.catalog,b.dataset.v2Consume,1));notify('Использована 1 шт. Лечение и временные эффекты применяются по описанию предмета.');}catch(e){notify(e.message);}});document.querySelectorAll('[data-v2-remove]').forEach(b=>b.onclick=()=>{if(!canEdit)return;const x=normalized.equipmentItems.find(x=>x.instanceId===b.dataset.v2Remove);modal('Убрать предмет из владения?',`<p>${esc(itemName(itemFor(x)))}</p><p>Предмет исчезнет из инвентаря и активного оснащения. Деньги не возвращаются.</p><button id="v2-confirm-remove" class="danger">Убрать предмет</button>`);$('#v2-confirm-remove').onclick=()=>{if(!canEdit)return;try{commit(V().removeEquipment(card,D.catalog,b.dataset.v2Remove));closeModal();}catch(e){error(e);}};});if($('#v2-roll')){['attribute','skill','weapon','distance'].forEach(id=>$('#v2-check-'+id).onchange=()=>{updateCheck();$('#v2-roll-result').textContent='Результат появится здесь';});updateCheck();$('#v2-roll').onclick=()=>{try{const c=check(),a=1+Math.floor(Math.random()*12),b=1+Math.floor(Math.random()*12);$('#v2-roll-result').textContent=`${a} + ${b} ${sign(c.modifier)} = ${a+b+c.modifier}`;}catch(e){notify(e.message);}};}}
 return {prepare,commit,parameters,perkHint,stateOptions,detail:x=>row(x,{full:true}),stat:(type,i)=>computed[type][(type==='attributes'?V().attributeIds:V().skillIds)[i]],bonus,equipment,decks,inventory,equipArmor,checks,bind,changeQuantity,addDialog,sign};
})();
